import{_ as e,o as s,c as t,a2 as o}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"江汉","description":"","frontmatter":{"title":"江汉","date":"2026-11-09T00:00:00.000Z","seq":28,"categories":["美文","诗经"],"collection":"《诗经 · 大雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·大雅/江汉.md","filePath":"blogs/诗经·大雅/江汉.md"}'),p={name:"blogs/诗经·大雅/江汉.md"};function r(c,a,l,n,_,i){return s(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="江汉" tabindex="-1">江汉 <a class="header-anchor" href="#江汉" aria-label="Permalink to &quot;江汉&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　荡之什</p><div class="poem"><p class="poem-stanza">江汉浮浮，武夫滔滔。匪安匪游，淮夷来求。既出我车，既设我旟。匪安匪舒，淮夷来铺。</p><p class="poem-stanza">江汉汤汤，武夫洸洸。经营四方，告成于王。四方既平，王国庶定。时靡有争，王心载宁。</p><p class="poem-stanza">江汉之浒，王命召虎：式辟四方，彻我疆土。匪疚匪棘，王国来极。于疆于理，至于南海。</p><p class="poem-stanza">王命召虎：来旬来宣。文武受命，召公维翰。无曰予小子，召公是似。肇敏戎公，用锡尔祉。</p><p class="poem-stanza">厘尔圭瓒，秬鬯一卣。告于文人，锡山土田。于周受命，自召祖命，虎拜稽首：天子万年！</p><p class="poem-stanza">虎拜稽首，对扬王休。作召公考：天子万寿！明明天子，令闻不已，矢其文德，洽此四国。</p></div>',3)])])}const u=e(p,[["render",r]]);export{d as __pageData,u as default};
